/** Internal: public `SparklineHoverEvent` plus cursor viewport coords for positioning the tooltip. */
export interface SparklineHoverInfo extends SparklineHoverEvent {
  left: number;
  top: number;
}

/** @internal
 * Given a sparkline config returns a DataFrame ready to be turned into Plot data set
 **/
export function preparePlotFrame(sparkline: FieldSparkline, config?: FieldConfig<GraphFieldConfig>): DataFrame {
  const length = sparkline.y.values.length;
  const yFieldConfig = {
    ...sparkline.y.config,
    ...config,
  };

  const xField = sparkline.x ?? {
    name: '',
    values: [...Array(length).keys()],
    type: FieldType.number,
    config: {},
  };

  let frame: DataFrame = {
    refId: 'sparkline',
    fields: [
      xField,
      {
        ...sparkline.y,
        config: yFieldConfig,
      },
    ],
    length,
  };

  if (!isLikelyAscendingVector(xField.values)) {
    frame = sortDataFrame(frame, 0);
  }

  return applyNullInsertThreshold({
    frame,
    refFieldPseudoMin: sparkline.timeRange?.from.valueOf(),
    refFieldPseudoMax: sparkline.timeRange?.to.valueOf(),
  });
}

/**
 * apply configuration defaults and ensure that the range is never two equal values.
 */
export function getYRange(alignedFrame: DataFrame): Range.MinMax {
  const field = alignedFrame.fields[1];
  let { min, max } = field.state?.range!;

  // enure that the min/max from the field config are respected.
  min = Math.min(min!, field.config.min ?? Infinity);
  max = Math.max(max!, field.config.max ?? -Infinity);

  // if noValue is set, ensure that it is included in the range as well
  const noValue = +field.config?.noValue!;
  if (!Number.isNaN(noValue)) {
    min = Math.min(min, noValue);
    max = Math.max(max, noValue);
  }

  const decimals = field.config.decimals ?? Math.max(guessDecimals(min), guessDecimals(max));

  // call roundDecimals to mirror what is going to eventually happen in uplot
  let roundedMin = roundDecimals(min, decimals);
  let roundedMax = roundDecimals(max, decimals);

  // if the rounded min and max are different,
  // we can return the real min and max.
  if (roundedMin !== roundedMax) {
    return [min, max];
  }

  // we are forced to tweak the min and max since they
  // will be treated as equal after rounding by uPlot.
  if (roundedMin === 0) {
    // both are zero
    roundedMax = 1;
  } else if (roundedMin < 0) {
    // both are negative
    roundedMin *= 2;
  } else {
    // both are positive
    roundedMax *= 2;
  }

  return [roundedMin, roundedMax];
}

const HIGHLIGHT_IDX_POINT_SIZE = 6;

const defaultConfig: GraphFieldConfig = {
  drawStyle: GraphDrawStyle.Line,
  showPoints: VisibilityMode.Auto,
  axisPlacement: AxisPlacement.Hidden,
  pointSize: 0,
};

export const prepareSeries = (
  sparkline: FieldSparkline,
  _theme: GrafanaTheme2,
  fieldConfig?: FieldConfig<GraphFieldConfig>,
  _showHighlights?: boolean
): { frame: DataFrame; warning?: string } => {
  const frame = nullToValue(preparePlotFrame(sparkline, fieldConfig));
  if (frame.fields.some((f) => f.values.length <= 1)) {
    return {
      warning: t(
        'grafana-ui.components.sparkline.warning.too-few-values',
        'Sparkline requires at least two values to render.'
      ),
      frame,
    };
  }
  // TODO:rgb(24, 24, 24) will address this.
  // if (showHighlights && typeof sparkline.highlightLine === 'number') {
  //   const highlightY = sparkline.highlightLine;
  //   const colorMode = getFieldColorModeForField(sparkline.y);
  //   const seriesColor = colorMode.getCalculator(sparkline.y, theme)(highlightY, 0);
  //   frame.fields.push({
  //     name: 'highlightLine',
  //     type: FieldType.number,
  //     values: new Array(frame.length).fill(highlightY),
  //     config: {
  //       color: {
  //         mode: FieldColorModeId.Fixed,
  //         fixedColor: colorManipulator.lighten(seriesColor, 0.5),
  //       },
  //       custom: {
  //         lineStyle: {
  //           fill: 'dash',
  //           dash: [5, 2],
  //         },
  //       },
  //     },
  //     state: {},
  //   });
  // }
  return { frame };
};

export const prepareConfig = (
  sparkline: FieldSparkline,
  dataFrame: DataFrame,
  theme: GrafanaTheme2,
  showHighlights?: boolean,
  enableHover?: boolean,
  onHover?: (hover: SparklineHoverInfo | null) => void
): UPlotConfigBuilder => {
  const builder = new UPlotConfigBuilder();
  const rangePad = HIGHLIGHT_IDX_POINT_SIZE / 2;
  // uPlot series/data index of the single y series (0 is the x field).
  let yFieldIndex = -1;

  // X is the first field in the aligned frame
  const xField = dataFrame.fields[0];

  if (enableHover) {
    // Crosshair + focused point at the hovered index, no drag/zoom. focus.prox Infinity keeps
    // the single series focused so hover works across the full width.
    const yField = dataFrame.fields.find((f) => f !== xField && f.type === FieldType.number);
    // Paint the cursor point a solid series color. uPlot's default cursor-point color fn reads
    // the builder's `frames`, which Sparkline never populates, so it would throw on gradient
    // series (e.g. TableNG's default hue). A solid color sidesteps that.
    const pointColor = yField ? getFieldSeriesColor(yField, theme).color : theme.colors.text.primary;
    builder.setCursor({
      show: true,
      x: true,
      y: false,
      drag: { x: false, y: false, setScale: false },
      focus: { prox: Infinity },
      points: { size: HIGHLIGHT_IDX_POINT_SIZE, stroke: pointColor, fill: pointColor },
    });
  } else {
    builder.setCursor({
      show: false,
      x: false,
      y: false,
    });
  }

  builder.addScale({
    scaleKey: 'x',
    orientation: ScaleOrientation.Horizontal,
    direction: ScaleDirection.Right,
    isTime: false, // xField.type === FieldType.time,
    range: () => {
      if (sparkline.x) {
        if (sparkline.timeRange && sparkline.x.type === FieldType.time) {
          return [sparkline.timeRange.from.valueOf(), sparkline.timeRange.to.valueOf()];
        }
        const vals = sparkline.x.values;
        return [vals[0], vals[vals.length - 1]];
      }
      return [0, sparkline.y.values.length - 1];
    },
  });

  builder.addAxis({
    scaleKey: 'x',
    theme,
    placement: AxisPlacement.Hidden,
    show: false,
  });

  for (let i = 0; i < dataFrame.fields.length; i++) {
    const field = dataFrame.fields[i];
    const config: FieldConfig<GraphFieldConfig> = field.config;
    const customConfig: GraphFieldConfig = {
      ...defaultConfig,
      ...config.custom,
    };

    if (field === xField || field.type !== FieldType.number) {
      continue;
    }

    const scaleKey = config.unit || '__fixed';
    yFieldIndex = i;
    builder.addScale({
      scaleKey,
      orientation: ScaleOrientation.Vertical,
      direction: ScaleDirection.Up,
      range: () => getYRange(dataFrame),
    });

    builder.addAxis({
      scaleKey,
      theme,
      placement: AxisPlacement.Hidden,
      show: false,
    });

    const colorMode = getFieldColorModeForField(field);
    const seriesColor = colorMode.getCalculator(field, theme)(0, 0);

    const hasHighlightIndex = showHighlights && typeof sparkline.highlightIndex === 'number';
    if (hasHighlightIndex) {
      builder.setPadding([rangePad, rangePad, rangePad, rangePad]);
    }

    const pointsMode =
      customConfig.drawStyle === GraphDrawStyle.Points || hasHighlightIndex
        ? VisibilityMode.Always
        : customConfig.showPoints;

    builder.addSeries({
      pxAlign: false,
      scaleKey,
      theme,
      colorMode,
      thresholds: config.thresholds,
      drawStyle: customConfig.drawStyle!,
      lineColor: customConfig.lineColor ?? seriesColor,
      lineWidth: customConfig.lineWidth,
      lineInterpolation: customConfig.lineInterpolation,
      showPoints: pointsMode,
      pointSize: hasHighlightIndex ? HIGHLIGHT_IDX_POINT_SIZE : customConfig.pointSize,
      pointsFilter: hasHighlightIndex ? [sparkline.highlightIndex!] : undefined,
      fillOpacity: customConfig.fillOpacity,
      fillColor: customConfig.fillColor,
      lineStyle: customConfig.lineStyle,
      gradientMode: customConfig.gradientMode,
      spanNulls: customConfig.spanNulls,
    });
  }

  if (enableHover && onHover && yFieldIndex >= 0) {
    const seriesIdx = yFieldIndex;
    const yField = dataFrame.fields[seriesIdx];
    const display = yField.display ?? getDisplayProcessor({ field: yField, theme });
    // Emit only on index change; emit null once when leaving a hovered point.
    let prevIdx: number | null | undefined;
    let pending: Omit<SparklineHoverInfo, 'display'> | undefined;
    let animationFrame: number | undefined;

    const clearHover = () => {
      if (animationFrame !== undefined) {
        cancelAnimationFrame(animationFrame);
        animationFrame = undefined;
      }
      pending = undefined;
      if (typeof prevIdx === 'number') {
        prevIdx = null;
        onHover(null);
      }
    };

    builder.addHook('destroy', clearHover);

    builder.addHook('setCursor', (u) => {
      const idx = u.cursor.idxs?.[seriesIdx] ?? null;
      const value = idx != null ? u.data[seriesIdx]?.[idx] : null;

      if (idx == null || value == null || !Number.isFinite(value)) {
        clearHover();
        return;
      }

      if (idx === prevIdx) {
        // Returning to the emitted point also supersedes a different queued point.
        pending = undefined;
        return;
      }

      pending = {
        index: idx,
        value,
        left: u.rect.left + (u.cursor.left ?? 0),
        top: u.rect.top + (u.cursor.top ?? 0),
      };
      if (animationFrame !== undefined) {
        return;
      }

      animationFrame = requestAnimationFrame(() => {
        animationFrame = undefined;
        const hover = pending;
        pending = undefined;
        if (hover && hover.index !== prevIdx) {
          prevIdx = hover.index;
          onHover({ ...hover, display: formattedValueToString(display(hover.value)) });
        }
      });
    });
  }

  return builder;
};
